function stableOrder(factIndex, level, values) {
  const offset = (factIndex * 3 + (level === "hard" ? 1 : 0)) % values.length;
  return values.slice(offset).concat(values.slice(0, offset));
}

const questions = concepts.flatMap((item, index) => {
  const [topic, source, medium, hard, answer, distractors, explanation] = item;
  return ["medium", "hard"].map((level) => {
    const choices = stableOrder(index + 1, level, [answer, ...distractors]);
    const format = index % 10 < 7 ? "written" : "multiple-choice";
    return {
      id: `${String(index + 1).padStart(3, "0")}-${level === "medium" ? "M" : "H"}`,
      topic,
      source,
      level,
      format,
      stem: level === "medium" ? medium : hard,
      answer,
      correctIndex: choices.indexOf(answer),
      ...(format === "multiple-choice" ? { options: choices } : {}),
      explanation,
    };
  });
});

module.exports = { questions };
